#!/usr/bin/env node
/**
 * Worth The Trip — Update app.js with real Stripe config.
 *
 * Reads `stripe-config.json` (generated by create-checkout-sessions.js) and
 * folds it into CONFIG in src/js/app.js:
 *   - stripePaymentLinks  (per-guide one-time checkout URLs)
 *   - stripeUnlockAllCheckoutUrl
 *   - unlockAllPriceId
 *
 * Safe to re-run (existing unlock-all fields are replaced, not duplicated).
 */

const fs = require('fs');
const path = require('path');

const appJsPath = path.join(__dirname, 'src/js/app.js');
const configPath = path.join(__dirname, 'stripe-config.json');

if (!fs.existsSync(configPath)) {
  console.error('ERROR: stripe-config.json not found. Run create-checkout-sessions.js first.');
  process.exit(1);
}

const config = JSON.parse(fs.readFileSync(configPath, 'utf8'));
let appJs = fs.readFileSync(appJsPath, 'utf8');

// 1) Replace the per-guide stripePaymentLinks block.
let paymentLinksBlock = "    stripePaymentLinks: {\n";
for (const [guideId, url] of Object.entries(config.stripePaymentLinks)) {
  paymentLinksBlock += `      '${guideId}': ${JSON.stringify(url)},\n`;
}
paymentLinksBlock += "    },\n";

const paymentLinksRegex = /    stripePaymentLinks: \{[\s\S]*?\n    \},/;
if (!paymentLinksRegex.test(appJs)) {
  console.error('ERROR: could not find stripePaymentLinks block in app.js');
  process.exit(1);
}
appJs = appJs.replace(paymentLinksRegex, paymentLinksBlock);

// 2) Remove any pre-existing unlock-all fields (keeps re-runs idempotent).
appJs = appJs.replace(
  /    stripeUnlockAllCheckoutUrl: .*?,\s*\n\s*    unlockAllPriceId: .*?,\s*\n?/s,
  ''
);

// 3) Insert the unlock-all fields before postPaymentUrl (re-indent postPaymentUrl safely).
const unlockAllBlock = `
    stripeUnlockAllCheckoutUrl: ${JSON.stringify(config.stripeUnlockAllCheckoutUrl)},
    unlockAllPriceId: ${JSON.stringify(config.unlockAllPriceId)},`;
const postPaymentUrlRegex = /^\s*postPaymentUrl: '\/guide',/m;
const postPaymentUrlMatch = appJs.match(postPaymentUrlRegex);
if (!postPaymentUrlMatch) {
  console.error('ERROR: postPaymentUrl not found in app.js');
  process.exit(1);
}
appJs = appJs.replace(postPaymentUrlRegex, unlockAllBlock + '    postPaymentUrl: \'/guide\',\n');

fs.writeFileSync(appJsPath, appJs);
console.log('Updated app.js with real Stripe config');
console.log('   unlockAllPriceId =', config.unlockAllPriceId);
